package java.util.concurrent;
public class CyclicBarrier {private final int parties;private final Runnable action;private int waiting;private boolean broken;public CyclicBarrier(int n){this(n,null);}public CyclicBarrier(int n,Runnable r){if(n<=0)throw new IllegalArgumentException();parties=n;action=r;}public int getParties(){return parties;}public int getNumberWaiting(){return waiting;}public boolean isBroken(){return broken;}public void reset(){waiting=0;broken=false;}public int await()throws InterruptedException,BrokenBarrierException{if(broken)throw new BrokenBarrierException();if(Thread.interrupted()){broken=true;throw new InterruptedException();}int i=parties-(++waiting);if(i==0){waiting=0;if(action!=null)try{action.run();}catch(RuntimeException e){broken=true;throw e;}return 0;}java.lang.VMThread.runPending();if(broken)throw new BrokenBarrierException();return i;}public int await(long n,TimeUnit u)throws InterruptedException,BrokenBarrierException,TimeoutException{if(u==null)throw new NullPointerException();return await();}}
